int main() {
    int k;
    ll n;
    cin >> k >> n; // 1 <= k <= 50; 0 <= n <= 10^18
    vector<ll> f(k), c(k);
    for (ll &x : f) {
        cin >> x;
        x = norm(x);
    }
    for (ll &x : c) {
        cin >> x; // c1,c2,...,ck in this order
