    Mat b = power(x, n);
    for (int i = 0; i < k; i++) {
        ll ans = 0;
        for (int j = 0; j < k; j++) ans = (ans + b.a[i][j] * f[j]) % MOD;
        cout << ans << ' ';
    }
    cout << "\n";
}

